DO $$
BEGIN
    IF NOT EXISTS (
            SELECT 1
            FROM m_blocking_reason_setting
            WHERE name_of_reason = 'MORA' AND level = 'CLIENT' AND priority = 1
        ) THEN
            INSERT INTO m_blocking_reason_setting (priority, description, name_of_reason, "level", is_enabled)
            VALUES(1, 'MORA', 'MORA', 'CLIENT', 1) ON CONFLICT DO NOTHING;
    END IF;
END $$;


DO $$
BEGIN
        IF NOT EXISTS (
                SELECT 1
                FROM m_blocking_reason_setting
                WHERE name_of_reason = 'MORA' AND level = 'CREDIT' AND priority = 1
            ) THEN
                INSERT INTO m_blocking_reason_setting (priority, description, name_of_reason, "level", is_enabled)
                VALUES(1, 'MORA', 'MORA', 'CREDIT', 1) ON CONFLICT DO NOTHING;
        END IF;
END $$;
